/* Straitjacket — Addressable Evidence instrument-panel stylesheet.
   Strict adherence to straitjacket/docs/VISUAL-DESIGN.md:
   - Semantic colours only (blue, amber, red, green, neutral)
   - Square corners (0px radius), 1px hairline rules, no gradients, no blur/glass, no glow. */

:root {
  --bg: #0D0F12;
  --ground: #15181D;
  --surface: #15181D;
  --surface2: #1C2026;
  --grid: #272C33;
  --ink: #ECEAE3;
  --muted: #8D939A;
  --faint: #7D848D;
  --blue: #6F96FF;
  --blue2: #263A68;
  --amber: #F0B429;
  --amber2: #58451D;
  --red: #FF7768;
  --red2: #542925;
  --green: #63D3A4;
  --panel: #15181D;

  --font-display: 'Space Grotesk Variable', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-body: 'Inter Variable', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  --bar-h: 48px;
  --progress: 0;

  /* 3D subject framing: right of the left instrument panel on desktop */
  --frame-x: 0.21;
  --frame-y: -0.02;
  --frame-fit: 1.12;
  color-scheme: dark;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.55;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
}

/* Fixed instrument top bar */
.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--bar-h);
  z-index: 20;
  background: var(--bg);
  border-bottom: 1px solid var(--grid);
}

.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  height: 100%;
  padding: 0 1.5rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  color: var(--ink);
  flex-shrink: 0;
}

.brand-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.12em;
}

.brand-ver {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--amber);
  border: 1px solid var(--amber2);
  background: var(--surface);
  padding: 0.1rem 0.38rem;
}

.chapter-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  overflow-x: auto;
  scrollbar-width: none;
}
.chapter-nav::-webkit-scrollbar { display: none; }

.chapter-nav a {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.35rem 0.65rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--muted);
  border: 1px solid transparent;
  white-space: nowrap;
  transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}

.chapter-nav a span {
  color: var(--faint);
}

.chapter-nav a:hover {
  color: var(--ink);
  border-color: var(--grid);
}

.chapter-nav a.is-active {
  color: var(--ink);
  border-color: var(--blue);
  background: var(--surface);
}

.chapter-nav a.is-active span {
  color: var(--blue);
}

.docs-link {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-decoration: none;
  color: var(--bg);
  background: var(--ink);
  padding: 0.35rem 0.75rem;
  flex-shrink: 0;
  transition: background 0.15s ease;
}

.docs-link:hover {
  background: var(--amber);
}

.progress-track {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2px;
  background: transparent;
}

.progress-fill {
  height: 100%;
  width: 100%;
  background: var(--blue);
  transform-origin: left center;
  transform: scaleX(var(--progress));
}

/* 3D Stage */
#stage {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  height: 100lvh;
  display: block;
  z-index: 0;
}

.chapter {
  position: relative;
  z-index: 1;
}

/* Typography & Instrument Panel Contents */
h1, h2 {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.08;
  text-transform: uppercase;
  margin: 0 0 0.65rem;
  color: var(--ink);
}

