// props.js: the three Straitjacket instruments on the metrology bench.
// Stand-ins render immediately on frame 1 and swap cleanly once the antigravity-3d installed models load.
import * as THREE from 'three';

export const PROPS = {
  gate: {
    at: [0, 0, 0],
    turn: 0,
    size: [1.65, 1.55, 0.95],
  },
  vault: {
    at: [3.6, 0, -0.35],
    turn: -0.22,
    size: [1.3, 1.55, 1.0],
  },
  anchor: {
    at: [7.0, 0, 0.25],
    turn: -0.15,
    size: [1.25, 1.35, 0.9],
  },
};

const pascal = (s) => s.split('_').filter(Boolean).map((p) => p[0].toUpperCase() + p[1] ? p[0].toUpperCase() + p.slice(1) : p.toUpperCase()).join('');

export function standIn([w, h, d]) {
  const geo = new THREE.BoxGeometry(w, h, d);
  geo.translate(0, h / 2, 0);
  const mesh = new THREE.Mesh(
    geo,
    new THREE.MeshStandardMaterial({ color: 0x3a404a, roughness: 0.6, metalness: 0.25 }),
  );
  mesh.name = 'stand-in';
  const group = new THREE.Group();
  group.add(mesh);
  return group;
}

export async function loadProp(entry, renderer) {
  if (!entry.module) return standIn(entry.size);
  const mod = await entry.module();
  const load = mod['load' + pascal(entry.asset)];
  if (typeof load !== 'function') throw new Error(`${entry.asset}: its loader has no export load${pascal(entry.asset)}`);
  return load({ renderer, baseUrl: new URL(`agy3d/${entry.asset}/`, document.baseURI).href, collision: false });
}

// shots.js: pure function of story time T.
// Every camera pose, prop visibility, and procedural evidence layer timing is computed here from T and chapter ids.

export const MOVE = 0.35;
export const REST = 0.7;
export const DESIGN_ASPECT = 1.6;

export const SHOTS = {
  intro: {
    pos: [-2.4, 2.3, 4.9],
    target: [0, 0.85, 0],
    fov: 30,
    span: 7,
    subject: 'gate',
  },
  flood: {
    pos: [-3.9, 2.1, 3.3],
    target: [-0.55, 0.82, 0.15],
    fov: 32,
    span: 8,
    via: { pos: [-3.6, 2.4, 4.5], target: [-0.3, 0.85, 0.1] },
    subject: 'gate',
  },
  digest: {
    pos: [1.65, 2.0, 5.2],
    target: [1.45, 0.82, -0.12],
    fov: 32,
    span: 9,
    via: { pos: [-0.4, 2.6, 5.8], target: [0.8, 0.85, -0.1] },
    subject: ['gate', 'vault'],
  },
  retrieve: {
    pos: [5.2, 2.15, 4.2],
    target: [3.6, 0.82, -0.35],
    fov: 30,
    span: 7,
    via: { pos: [3.6, 2.5, 5.2], target: [3.0, 0.82, -0.25] },
    subject: 'vault',
  },
  anchors: {
    pos: [8.8, 2.0, 4.3],
    target: [7.0, 0.74, 0.25],
    fov: 30,
    span: 7,
    via: { pos: [7.0, 2.45, 5.1], target: [5.8, 0.78, 0.05] },
    subject: 'anchor',
  },
  handoff: {
    pos: [3.5, 4.4, 12.2],
    target: [3.5, 0.75, 0.0],
    fov: 32,
    span: 14,
    push: 0.02,
    via: { pos: [6.8, 3.6, 8.6], target: [4.8, 0.75, 0.1] },
    // Establishing shot of all three instruments together: no single subject
  },
};

// All three instruments stay standing on the continuous evidence bench so transitions never cross empty void.
export const SHOW = {
  gate: ['intro', 'flood', 'digest', 'retrieve', 'anchors', 'handoff'],
  vault: ['intro', 'flood', 'digest', 'retrieve', 'anchors', 'handoff'],
  anchor: ['intro', 'flood', 'digest', 'retrieve', 'anchors', 'handoff'],
};

const DEFAULT_PUSH = 0.05;
const clamp01 = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);

export function timeline(ids) {
  return (id, local = 0) => {
    const i = ids.indexOf(id);
    if (i < 0) throw new Error(`at("${id}"): no chapter of the page has that id`);
    return i + local;
  };
}

export const ramp = (T, a, b) => {
  const t = clamp01((T - a) / (b - a));
  return t * t * t * (t * (t * 6 - 15) + 10);
};

function monotone(ts, ys) {
  const n = ts.length, d = [], m = new Array(n).fill(0);
  if (n === 1) return () => ys[0];
  for (let i = 0; i < n - 1; i++) d.push((ys[i + 1] - ys[i]) / (ts[i + 1] - ts[i]));
  for (let i = 1; i < n - 1; i++) {
    if (d[i - 1] * d[i] <= 0) continue;
    const w1 = 2 * (ts[i + 1] - ts[i]) + (ts[i] - ts[i - 1]);
    const w2 = (ts[i + 1] - ts[i]) + 2 * (ts[i] - ts[i - 1]);
    m[i] = (w1 + w2) / (w1 / d[i - 1] + w2 / d[i]);
  }
  return (T) => {
    if (T <= ts[0]) return ys[0];
    if (T >= ts[n - 1]) return ys[n - 1];
    let i = 0;
    while (T > ts[i + 1]) i++;
    const h = ts[i + 1] - ts[i], t = (T - ts[i]) / h, t2 = t * t, t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * ys[i] + (t3 - 2 * t2 + t) * h * m[i]
      + (-2 * t3 + 3 * t2) * ys[i + 1] + (t3 - t2) * h * m[i + 1];
  };
}

const pushed = (s) => {
  const k = 1 - (s.push ?? DEFAULT_PUSH);
  return { ...s, pos: s.pos.map((p, j) => s.target[j] + (p - s.target[j]) * k) };
};

function keysFor(ids) {
  const keys = [];
  ids.forEach((id, i) => {
    const s = SHOTS[id];
    if (i === 0) keys.push([0, s, 0]);
    else {
      if (s.via) keys.push([i + MOVE / 2, { ...s, ...s.via }, i - 0.5]);
      keys.push([i + MOVE, s, i]);
    }
    keys.push([i + 1, pushed(s), i]);
  });
  return keys;
}

let cached = null;
function curves(ids) {
  const sig = ids.join('|');
  if (cached && cached.sig === sig) return cached;
  const keys = keysFor(ids), ts = keys.map((k) => k[0]);
  const chan = (f) => monotone(ts, keys.map(f));
  cached = {
    sig,
    pos: [0, 1, 2].map((j) => chan((k) => k[1].pos[j])),
    target: [0, 1, 2].map((j) => chan((k) => k[1].target[j])),
    fov: chan((k) => k[1].fov),
    span: chan((k) => k[1].span),
    shot: chan((k) => k[2]),
    show: Object.fromEntries(Object.entries(SHOW).map(([name...[3246 more chars]

// evidence.js: custom-shader metrology coordinate deck + single-draw-call InstancedMesh byte slabs.
// Every visual state is a pure deterministic function of state.layer from shots.js.
// Shader rules (libraries.md + VISUAL-DESIGN.md):
//   - All chosen colours are passed as THREE.Color uniforms (linear conversion handled by three.js).
//   - Every procedural line and rail edge is smoothed with fwidth().
//   - Strictly semantic colours (blue, amber, red, green, neutral); zero glow, zero particles.
import * as THREE from 'three';
import CustomShaderMaterial from 'three-custom-shader-material/vanilla';

const PALETTE = {
  ground: '#15181D',
  grid: '#272C33',
  gridMajor: '#343B45',
  railOff: '#1F242C',
  blue: '#6F96FF',
  amber: '#F0B429',
  red: '#FF7768',
  green: '#63D3A4',
  neutral: '#535B66',
  neutralDark: '#2E343D',
};

const clamp01 = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
const mix = (a, b, t) => a + (b - a) * t;

export function createEvidenceLayer(scene) {
  // 1. Metrology coordinate deck (CustomShaderMaterial on MeshStandardMaterial: keeps full PBR lighting + shadows)
  const deckUniforms = {
    uBase: { value: new THREE.Color(PALETTE.ground) },
    uGrid: { value: new THREE.Color(PALETTE.grid) },
    uGridMajor: { value: new THREE.Color(PALETTE.gridMajor) },
    uRailOff: { value: new THREE.Color(PALETTE.railOff) },
    uBlue: { value: new THREE.Color(PALETTE.blue) },
    uAmber: { value: new THREE.Color(PALETTE.amber) },
    uRed: { value: new THREE.Color(PALETTE.red) },
    uGreen: { value: new THREE.Color(PALETTE.green) },
    uFlood: { value: 0 },
    uDigest: { value: 0 },
    uRetrieve: { value: 0 },
    uAnchor: { value: 0 },
    uHandoff: { value: 0 },
  };

  const deckMaterial = new CustomShaderMaterial({
    baseMaterial: THREE.MeshStandardMaterial,
    roughness: 0.92,
    metalness: 0.08,
    uniforms: deckUniforms,
    vertexShader: /* glsl */ `
      varying vec3 vWorld;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uBase;
      uniform vec3 uGrid;
      uniform vec3 uGridMajor;
      uniform vec3 uRailOff;
      uniform vec3 uBlue;
      uniform vec3 uAmber;
      uniform vec3 uRed;
      uniform vec3 uGreen;
      uniform float uFlood;
      uniform float uDigest;
      uniform float uRetrieve;
      uniform float uAnchor;
      uniform float uHandoff;
      varying vec3 vWorld;

      float gridLine(vec2 p, float stepSize, float halfWidth) {
        vec2 q = abs(fract(p / stepSize - 0.5) - 0.5) * stepSize;
        float d = min(q.x, q.y) - halfWidth;
        float w = max(fwidth(d), 0.001);
        return 1.0 - smoothstep(-w, w, d);
      }

      float segMask(vec2 p, vec2 a, vec2 b, float halfWidth) {
        vec2 pa = p - a, ba = b - a;
        float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-5), 0.0, 1.0);
        float d = length(pa - ba * h) - halfWidth;
        float w = max(fwidth(d), 0.001);
        return 1.0 - smoothstep(-w, w, d);
      }

      void main() {
        vec2 p = vWorld.xz;
        vec3 col = uBase;

        // Precision 0.5 m minor / 2.0 m major metrology coordinate grid
        float minor = gridLine(p, 0.5, 0.006);
        float major = gridLine(p, 2.0, 0.011);
        float benchFade = 1.0 - smoothstep(10.0, 24.0, length(p - vec2(3.2, 0.0)));
        col = mix(col, uGrid, minor * 0.55 * benchFade);
        col = mix(col, uGridMajor, major * 0.8 * benchFade);

        // Main physical evidence bus along the bench: intake -> gate -> vault -> anchor -> exit
        float intakeRail = segMask(p, vec2(-3.2, 0.0), vec2(-0.5, 0.0), 0.055);
        float digestRail = segMask(p, vec2(0.5, 0.0), vec2(3.1, -0.35), 0.045);
        float retrieveRail = segMask(p, vec2(3.6, 0.15), vec2(3.6, 1.65), 0.045);
        float anchorRail = segMask(p, vec2(4.1, -0.25), vec2(6.5, 0.25), 0.045);
        float exitRail = segMask(p, vec2(7.5, 0.25), vec2(9.2, 0.25), 0.045)...[10798 more chars]

// stage.js: Three.js WebGLRenderer, RoomEnvironment, PCFShadowMap, detect-gpu quality tiering,
// CustomShaderMaterial metrology deck, InstancedMesh byte slabs, troika-three-text 3D labels,
// and antigravity-3d prop loader with stand-in fallback.
import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { getGPUTier } from 'detect-gpu';
import { Text } from 'troika-three-text';
import { PROPS, loadProp, standIn } from './props.js';
import { DESIGN_ASPECT } from './shots.js';
import { createEvidenceLayer } from './evidence.js';

const KEY_DIR = new THREE.Vector3(-0.45, 1.0, 0.55).normalize();
const css = (name, fallback) => getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback;

function contactShadow() {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, 'rgba(0,0,0,0.6)');
  grad.addColorStop(0.55, 'rgba(0,0,0,0.24)');
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 128, 128);
  const map = new THREE.CanvasTexture(c);
  map.colorSpace = THREE.SRGBColorSpace;
  const geo = new THREE.PlaneGeometry(1, 1);
  geo.rotateX(-Math.PI / 2);
  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ map, transparent: true, depthWrite: false }));
  mesh.position.y = 0.003;
  mesh.renderOrder = 1;
  return mesh;
}

function makeLabel(text, colorHex, yHeight) {
  const t = new Text();
  t.text = text;
  t.font = new URL('fonts/jetbrains-mono-600.woff', document.baseURI).href;
  t.fontSize = 0.095;
  t.letterSpacing = 0.06;
  t.anchorX = 'center';
  t.anchorY = 'bottom';
  t.color = colorHex;
  t.outlineWidth = 0.012;
  t.outlineColor = '#0D0F12';
  t.position.set(0, yHeight, 0);
  return t;
}

export function createStage(canvas, { phone = false, onChange = () => {}, onLost = () => {} } = {}) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
  renderer.toneMapping = THREE.NeutralToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFShadowMap;

  const scene = new THREE.Scene();
  const bg = new THREE.Color(css('--bg', '#0D0F12'));
  scene.background = bg;
  scene.fog = new THREE.Fog(bg, 15, 42);

  function environment() {
    if (scene.environment) scene.environment.dispose();
    const pmrem = new THREE.PMREMGenerator(renderer);
    scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    pmrem.dispose();
  }
  environment();
  scene.environmentIntensity = 0.62;

  const key = new THREE.DirectionalLight(0xffffff, 2.5);
  key.castShadow = true;
  key.shadow.mapSize.set(phone ? 1024 : 2048, phone ? 1024 : 2048);
  key.shadow.bias = -0.0004;
  key.shadow.normalBias = 0.02;
  key.shadow.radius = 2.5;
  key.shadow.camera.near = 1;
  key.shadow.camera.far = 60;
  scene.add(key, key.target);

  // Subtle cool rim directional light (no shadow) to separate dark machined steel edges from #0D0F12 void
  const rim = new THREE.DirectionalLight('#b7c8e8', 0.55);
  rim.position.set(6, 5, -8);
  scene.add(rim);

  // Metrology coordinate floor + instanced byte slabs
  const evidence = createEvidenceLayer(scene);

  const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 100);

  // GPU tier check in parallel (offline benchmarksURL, never disables 3D)
  let maxDpr = phone ? 1.5 : 2;
  const gpuReady = Promise.race([
    getGPUTier({
      glContext: renderer.getContext(),
      benchmarksURL: new URL('detect-gpu', document.baseURI).href,
    }),
    new Promise((resolve) => setTimeout(() => resolve({ tier: 1, type: 'TIMEOUT' }), 1500)),
  ]).then((gpu) => {
    const tier = gpu && typeof gpu.tier === 'number' ? gpu.tier : 1;
    maxDpr = phone ? Math.min(1.5, tier >= 2 ? 1.5 : 1.25) : (tier >= 2 ? 2 : 1.5);
