function label(name, object, prop) {
  if (prop && !props[prop]) throw new Error(`label ${name}: no prop "${prop}" in props.js`);
  (prop ? props[prop].holder : scene).add(object);
  labels[name] = object;
  if (typeof object.sync === 'function') object.sync(onChange);
  onChange();
  return object;
}

