.webgl-on .panel {
  position: fixed;
  top: calc(var(--bar-h) + 5vh);
  left: 3.5vw;
  width: min(30rem, 35vw);
  max-height: calc(100vh - var(--bar-h) - 9vh);
  overflow-y: auto;
  overflow-x: hidden;
  padding: 1.35rem 1.5rem;
  background: var(--panel);
  border: 1px solid var(--grid);
  border-top: 2px solid var(--blue);
  border-radius: 0;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.3s ease, visibility 0.3s ease;
