        }));
        const panels = [...document.querySelectorAll(".panel")].map(p => ({
          id: p.parentElement.id,
          rect: p.getBoundingClientRect().toJSON(),
          op: getComputedStyle(p).opacity,
          vis: getComputedStyle(p).visibility,
          ov: getComputedStyle(p).overflowY,
          scrollH: p.scrollHeight,
          clientH: p.clientHeight,
        }));
        return { pct: ${pct}, scrollY, els, panels };
      })()`
    });
