function initScrollUI() {
  // Smooth wheel scroll on desktop (Lenis automatically respects prefers-reduced-motion & keeps touch native)
  const lenis = new Lenis({ allowNestedScroll: true });
  lenis.on('scroll', ScrollTrigger.update);
  gsap.ticker.add((seconds) => lenis.raf(seconds * 1000));
  gsap.ticker.lagSmoothing(0);

  site.scrollWith = (y) => lenis.scrollTo(y);

  // Progress bar synced with ScrollTrigger (HTML-only effect; 3D stays pure function of scrollY)
  ScrollTrigger.create({
    trigger: '#story',
    start: 'top top',
    end: 'bottom bottom',
    onUpdate: (self) => {
      root.style.setProperty('--progress', self.progress.toFixed(4));
    },
  });
}
